// Bundle Apache-2.0 Dizione rules as inert source for execution inside QuickJS WASM.
// Usage: bun tools/build-english.mjs
const root = new URL("../", import.meta.url);
const result = await Bun.build({
  entrypoints: [new URL("web/vendor/dizione/vm-entry.js", root).pathname],
  target: "browser",
  format: "iife",
  minify: false,
});
if (!result.success) throw new AggregateError(result.logs, "Dizione rules bundle failed");
const source = await result.outputs[0].text();
await Bun.write(new URL("web/dizione-rules.js", root),
  "// Generated by tools/build-english.mjs. Dizione / tiny-voca, Apache-2.0.\n" +
  "// Inert source: evaluate only inside QuickJS WebAssembly.\n" +
  "export const DIZIONE_RULES = " + JSON.stringify(source) + ";\n");
console.log(`Dizione QuickJS rules: ${source.length} source characters`);
